113	        if (requisicao.getCupom() != null && !requisicao.getCupom().isEmpty()) {
114	            TipoCupom tipoCupom = TipoCupom.fromString(requisicao.getCupom());
115	            if (tipoCupom == null) {
116	                throw new ValidacaoException("CUPOM_INVALIDO");
117	            }
118	
119	            BigDecimal subtotal = calcularSubtotal(requisicao.getItens());
120	            CupomStrategy estrategiaCupom = CupomFactory.criar(tipoCupom);
121	            if (!estrategiaCupom.isAplicavel(subtotal)) {
122	                throw new ValidacaoException("CUPOM_NAO_APLICAVEL");
123	            }
124	        }
125	
126	        // 8. Validar forma de pagamento
127	        FormaPagamento formaPagamento = FormaPagamento.fromString(requisicao.getFormaPagamento());
128	        if (formaPagamento == null) {
129	            throw new ValidacaoException("FORMA_PAGAMENTO_INVALIDA");
130	        }
131	
132	        // 9. Validar parcelas
133	        Integer parcelas = requisicao.getParcelas();
134	        PagamentoStrategy estrategiaPagamento = PagamentoFactory.criar(formaPagamento);
135	        if (parcelas < 1 || parcelas > estrategiaPagamento.getParcelasMaximas()) {
136	            throw new ValidacaoException("PARCELAMENTO_INVALIDO");
137	        }
138	
139	        // 10. Validar disponibilidade de forma de pagamento
140	        BigDecimal subtotalCalc = calcularSubtotal(requisicao.getItens());
141	        BigDecimal descontoCupom = BigDecimal.ZERO;
142	        if (requisicao.getCupom() != null && !requisicao.getCupom().isEmpty()) {
143	            TipoCupom tipoCupom = TipoCupom.fromString(requisicao.getCupom());
144	            CupomStrategy estrategiaCupom = CupomFactory.criar(tipoCupom);
145	            descontoCupom = estrategiaCupom.calcularDesconto(subtotalCalc, BigDecimal.ZERO, requisicao.getItens());
146	        }
147	        BigDecimal freteCalc = estrategiaEntrega.calcularFrete(pesoTotal);
148	        BigDecimal seguroCalc = SeguroFactory.calcularSeguro(regiao, subtotalCalc);
149	        BigDecimal totalParaValidacao = subtotalCalc.subtract(descontoCupom).add(freteCalc).add(seguroCalc);
150	
151	        if (!estrategiaPagamento.isDisponivel(totalParaValidacao)) {
152	            throw new ValidacaoException("FORMA_PAGAMENTO_INDISPONIVEL");
153	        }
154	    }
155	
156	    private BigDecimal calcularSubtotal(List<Item> itens) {
157	        return itens.stream()
158	            .map(item -> new BigDecimal(item.getPrecoUnitario())
159	                .multiply(new BigDecimal(item.getQuantidade())))
160	            .reduce(BigDecimal.ZERO, BigDecimal::add);
161	    }
162	
163	    private Double calcularPesoTotal(List<Item> itens) {
164	        return itens.stream()
165	            .mapToDouble(item -> item.getPesoKg() * item.getQuantidade())
166	            .sum();
167	    }
168	}
