1	package com.loja.checkout.strategy;
2	
3	import java.math.BigDecimal;
4	import java.math.RoundingMode;
5	import java.math.MathContext;
6	
7	public class PagamentoCartao implements PagamentoStrategy {
8	
9	    private static final BigDecimal TAXA_JUROS_MENSAL = new BigDecimal("0.0199");
10	
11	    @Override
12	    public BigDecimal calcularAjuste(BigDecimal total, Integer parcelas) {
13	        if (parcelas <= 3) {
14	            return new BigDecimal("0.00");
15	        }
16	
17	        BigDecimal valorComJuros = calcularTotalComJuros(total, parcelas);
18	        return valorComJuros.subtract(total);
19	    }
20	
21	    private BigDecimal calcularTotalComJuros(BigDecimal total, Integer parcelas) {
22	        BigDecimal um = new BigDecimal("1");
23	        BigDecimal taxa = TAXA_JUROS_MENSAL;
24	        BigDecimal n = new BigDecimal(parcelas);
25	
26	        MathContext mc = new MathContext(64, RoundingMode.HALF_EVEN);
27	        BigDecimal umMaisTaxa = um.add(taxa, mc);
28	        BigDecimal expoente = umMaisTaxa.pow(-parcelas.intValue(), mc);
29	        BigDecimal denominador = um.subtract(expoente, mc);
30	
31	        BigDecimal parcelaBruta = total
32	            .multiply(taxa, mc)
33	            .divide(denominador, 10, RoundingMode.HALF_EVEN);
34	
35	        BigDecimal parcela = parcelaBruta.setScale(2, RoundingMode.HALF_EVEN);
36	        return parcela.multiply(n);
37	    }
38	
39	    @Override
40	    public BigDecimal calcularValorParcela(BigDecimal valorFinal, Integer parcelas) {
41	        BigDecimal parcela = valorFinal.divide(new BigDecimal(parcelas), 2, RoundingMode.HALF_EVEN);
42	        return parcela;
43	    }
44	
45	    @Override
46	    public Integer getParcelasMaximas() {
47	        return 12;
48	    }
49	
50	    @Override
51	    public boolean isDisponivel(BigDecimal total) {
52	        return true;
53	    }
54	}
